checks.expression:
invariant(false, "POLICY_" + rule, "Required translator policy was not established at " + boundary + ".", {
      audit: "policy", line, boundary, phase: phase(),
      ...(active ? {section: sectionIndex + 1, operation: section.name, ...(path ? {path} : {})} : {}),
      ...(pointer ? {planPointer: pointer} : {}), expected, observed: {...observed}
    })

check(Object.keys(observed).length === Object.keys(expected).length && Object.entries(expected).every(([key, values]) => {
        const actual = observed[key];
        values.sort((a, b) => a - b);
        return actual?.length === values.length && values.every(v => Number.isFinite(v)) &&
          actual.sort((a, b) => a - b).every((v, i) => v === values[i]);
      }), "WORDS", "Final G-code words disagree with the validated command.", context)

return {schema: "linuxcnc-next-nc/artifact-identity/1", status: valid ? (expectedSHA256 === observedSHA256 ? "match" : "mismatch") : expected == null ? "not_recorded" : "invalid_hash",
    file, bytes, expectedSHA256, observedSHA256, checkedUTC: new Date().toISOString(),
    scope: "Exact bytes read compared with the archived candidate hash; not authenticity, current controller loading or machine acceptance."};
